/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_unicode_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER cascade_soft_delete_legal_entity_cr
AFTER UPDATE ON legal
FOR EACH ROW
BEGIN
    DECLARE days_to_delete INT;
    
    IF OLD.DeleteDatetime IS NULL AND NEW.DeleteDatetime IS NOT NULL THEN
        IF is_automatic_deletion_enabled() THEN
            SET days_to_delete = get_days_to_automatically_delete();
            
            IF days_to_delete = 0 THEN
                UPDATE changerequest 
                SET Deleted_At = NEW.DeleteDatetime,
                    LastUserChange = NULL,
                    scheduled_delete_at = NULL
                WHERE Reference = CONCAT('Legal Entity ', NEW.ID) 
                  AND Deleted_At IS NULL;
            ELSE
                UPDATE changerequest 
                SET scheduled_delete_at = DATE_ADD(NEW.DeleteDatetime, INTERVAL days_to_delete DAY),
                    LastUserChange = NULL
                WHERE Reference = CONCAT('Legal Entity ', NEW.ID) 
                  AND Deleted_At IS NULL
                  AND scheduled_delete_at IS NULL;
            END IF;
        END IF;
    END IF;
    IF OLD.DeleteDatetime IS NOT NULL AND NEW.DeleteDatetime IS NULL THEN
        UPDATE changerequest 
        SET Deleted_At = NULL,
            scheduled_delete_at = NULL,
            Updated_At = NOW(),
            LastUserChange = NULL
        WHERE Reference = CONCAT('Legal Entity ', NEW.ID);
    END IF;
END */;;
DELIMITER ;
