DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER cascade_soft_delete_org_unit_cr
AFTER UPDATE ON org_unit
FOR EACH ROW
BEGIN
    DECLARE days_to_delete INT;
    
    IF OLD.deleted_Date IS NULL AND NEW.deleted_Date IS NOT NULL THEN
        IF is_automatic_deletion_enabled() THEN
            SET days_to_delete = get_days_to_automatically_delete();
            
            IF days_to_delete = 0 THEN
                UPDATE changerequest 
                SET Deleted_At = NEW.deleted_Date,
                    LastUserChange = NULL,
                    scheduled_delete_at = NULL
                WHERE Reference = CONCAT('Org Unit ', NEW.ID) 
                  AND Deleted_At IS NULL;
            ELSE
                UPDATE changerequest 
                SET scheduled_delete_at = DATE_ADD(NEW.deleted_Date, INTERVAL days_to_delete DAY),
                    LastUserChange = NULL
                WHERE Reference = CONCAT('Org Unit ', NEW.ID) 
                  AND Deleted_At IS NULL
                  AND scheduled_delete_at IS NULL;
            END IF;
        END IF;
    END IF;
    IF OLD.deleted_Date IS NOT NULL AND NEW.deleted_Date IS NULL THEN
        UPDATE changerequest 
        SET Deleted_At = NULL,
            scheduled_delete_at = NULL,
            Updated_At = NOW(),
            LastUserChange = NULL
        WHERE Reference = CONCAT('Org Unit ', NEW.ID);
    END IF;
END */;;
