/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER cascade_soft_delete_process_cr
AFTER UPDATE ON process
FOR EACH ROW
BEGIN
    DECLARE days_to_delete INT;
    
    IF OLD.DeletedDatetime IS NULL AND NEW.DeletedDatetime IS NOT NULL THEN
        IF is_automatic_deletion_enabled() THEN
            SET days_to_delete = get_days_to_automatically_delete();
            
            IF days_to_delete = 0 THEN
                UPDATE changerequest 
                SET Deleted_At = NEW.DeletedDatetime,
                    LastUserChange = COALESCE(NEW.lastupdateuser_id, NULL),
                    scheduled_delete_at = NULL
                WHERE Reference = CONCAT('Process ', NEW.ID) 
                  AND Deleted_At IS NULL;
            ELSE
                UPDATE changerequest 
                SET scheduled_delete_at = DATE_ADD(NEW.DeletedDatetime, INTERVAL days_to_delete DAY),
                    LastUserChange = COALESCE(NEW.lastupdateuser_id, NULL)
                WHERE Reference = CONCAT('Process ', NEW.ID) 
                  AND Deleted_At IS NULL
                  AND scheduled_delete_at IS NULL;
            END IF;
        END IF;
    END IF;
    IF OLD.DeletedDatetime IS NOT NULL AND NEW.DeletedDatetime IS NULL THEN
        UPDATE changerequest 
        SET Deleted_At = NULL,
            scheduled_delete_at = NULL,
            Updated_At = NOW(),
            LastUserChange = COALESCE(NEW.lastupdateuser_id, NULL)
        WHERE Reference = CONCAT('Process ', NEW.ID);
    END IF;
END */;;
DELIMITER ;
