/bpmn2:collaboration>\n  <bpmn2:process id=\"changerequest-Wf-Committee-1768127318174\" name=\"DefaultWorkflow-1-Committee\" isExecutable=\"true\">\n    <bpmn2:laneSet id=\"changerequest-Wf-Committee-1768127318174-laneset-1768127318174\" name=\"changerequest-Wf-Committee-1768127318174-laneset-1768127318174\">\n      <bpmn2:lane id=\"changerequest-Wf-Committee-1768127318174-laneset-1768127318174-lane-9\" name=\"3:Committee Owner\">\n        <bpmn2:flowNodeRef>StartEvent_00htd7i</bpmn2:flowNodeRef>\n        <bpmn2:flowNodeRef>EndEvent_1ge7wxq</bpmn2:flowNodeRef>\n        <bpmn2:flowNodeRef>UserTask_09wiquf</bpmn2:flowNodeRef>\n        <bpmn2:flowNodeRef>UserTask_1fytr6i</bpmn2:flowNodeRef>\n        <bpmn2:flowNodeRef>UserTask_1r85tib</bpmn2:flowNodeRef>\n        <bpmn2:flowNodeRef>ExclusiveGateway_1m7r66b</bpmn2:flowNodeRef>\n        <bpmn2:flowNodeRef>UserTask_0un1rwo</bpmn2:flowNodeRef>\n        <bpmn2:flowNodeRef>EndEvent_02vx5jj</bpmn2:flowNodeRef>\n      </bpmn2:lane>\n      <bpmn2:lane id=\"Lane_1alu7bq\" name=\"R01:Requestor\" />\n    </bpmn2:laneSet>\n    <bpmn2:sequenceFlow id=\"SequenceFlow_0v3fa35\" sourceRef=\"UserTask_0un1rwo\" targetRef=\"EndEvent_1ge7wxq\" />\n    <bpmn2:startEvent id=\"StartEvent_00htd7i\" name=\"Start\">\n      <bpmn2:outgoing>SequenceFlow_0tsxvfo</bpmn2:outgoing>\n    </bpmn2:startEvent>\n    <bpmn2:endEvent id=\"EndEvent_1ge7wxq\" name=\"End-Comms\">\n      <bpmn2:incoming>SequenceFlow_0v3fa35</bpmn2:incoming>\n    </bpmn2:endEvent>\n    <bpmn2:userTask id=\"UserTask_09wiquf\" name=\"Implement\" camunda:dueDate=\"5\">\n      <bpmn2:documentation>The approved request is implemented. All necessary communications are made. The change request can then be closed.</bpmn2:documentation>\n      <bpmn2:incoming>SequenceFlow_17adjgx</bpmn2:incoming>\n      <bpmn2:outgoing>SequenceFlow_1s6hi6r</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:userTask id=\"UserTask_1fytr6i\" name=\"Assessment\" camunda:dueDate=\"5\">\n      <bpmn2:documentation>Perform all necessary work to review and assess the request and understand the impact, or rework proposal. Prepare recommendations.</bpmn2:documentation>\n      <bpmn2:incoming>SequenceFlow_1o7zucb</bpmn2:incoming>\n      <bpmn2:incoming>SequenceFlow_0tsxvfo</bpmn2:incoming>\n      <bpmn2:outgoing>SequenceFlow_07gbhm3</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:userTask id=\"UserTask_1r85tib\" name=\"Approval\" camunda:dueDate=\"5\">\n      <bpmn2:documentation>Recommendations are assessed for completeness and approval. Should this request be implemented?</bpmn2:documentation>\n      <bpmn2:incoming>SequenceFlow_07gbhm3</bpmn2:incoming>\n      <bpmn2:outgoing>SequenceFlow_115x6b0</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:exclusiveGateway id=\"ExclusiveGateway_1m7r66b\" name=\"Decision\">\n      <bpmn2:incoming>SequenceFlow_115x6b0</bpmn2:incoming>\n      <bpmn2:outgoing>SequenceFlow_1o7zucb</bpmn2:outgoing>\n      <bpmn2:outgoing>SequenceFlow_17adjgx</bpmn2:outgoing>\n      <bpmn2:outgoing>SequenceFlow_0ejcxta</bpmn2:outgoing>\n    </bpmn2:exclusiveGateway>\n    <bpmn2:sequenceFlow id=\"SequenceFlow_0tsxvfo\" sourceRef=\"StartEvent_00htd7i\" targetRef=\"UserTask_1fytr6i\" />\n    <bpmn2:sequenceFlow id=\"SequenceFlow_17adjgx\" name=\"Approved\" sourceRef=\"ExclusiveGateway_1m7r66b\" targetRef=\"UserTask_09wiquf\">\n      <bpmn2:conditionExpression xsi:type=\"bpmn2:tFormalExpression\"><![CDATA[${last_approval == \'Approved\'}]]></bpmn2:conditionExpression>\n    </bpmn2:sequenceFlow>\n    <bpmn2:sequenceFlow id=\"SequenceFlow_1o7zucb\" name=\"Rework\" sourceRef=\"ExclusiveGateway_1m7r66b\" targetRef=\"UserTask_1fytr6i\">\n      <bpmn2:documentation>A decision cannot be made on the information available. The request is returned for additional actions. Ensure that reasons for rework are stated in the comments, or the analysis field on the summary tab.</bpmn2:documentation>\n      <bpmn2:conditionExpression xsi:type=\"bpmn2:tFormalExpression\"><![CDATA[${last_approval == \'Rework\'}]]></bpmn2:conditionExpression>\n    </bpmn2:sequenceFlow>\n    <bpmn2:sequenceFlow id=\"SequenceFlow_07gbhm3\" sourceRef=\"UserTask_1fytr6i\" targetRef=\"UserTask_1r85tib\" />\n    <bpmn2:sequenceFlow id=\"SequenceFlow_115x6b0\" sourceRef=\"UserTask_1r85tib\" targetRef=\"ExclusiveGateway_1m7r66b\" />\n    <bpmn2:userTask id=\"UserTask_0un1rwo\" name=\"Communicate\" camunda:dueDate=\"5\">\n      <bpmn2:documentation>Change Request object should clearly outline reasons for rejection (e.g. in Resolution), requester and other interested parties should be informed. Ensure that these reasons are either recorded in comments or appended to the request, so we have a record. Request can then be closed.</bpmn2:documentation>\n      <bpmn2:incoming>SequenceFlow_0ejcxta</bpmn2:incoming>\n      <bpmn2:outgoing>SequenceFlow_0v3fa35</bpmn2:outgoing>\n    </bpmn2:userTask>\n    <bpmn2:sequenceFlow id=\"SequenceFlow_0ejcxta\" name=\"Rejected\" sourceRef=\"ExclusiveGateway_1m7r66b\" targetRef=\"UserTask_0un1rwo\">\n      <bpmn2:conditionExpression xsi:type=\"bpmn2:tFormalExpression\"><![CDATA[${last_approval == \'Rejected\'}]]></bpmn2:conditionExpression>\n    </bpmn2:sequenceFlow>\n    <bpmn2:endEvent id=\"EndEvent_02vx5jj\" name=\"End-Implement\">\n      <bpmn2:incoming>SequenceFlow_1s6hi6r</bpmn2:incoming>\n    </bpmn2:endEvent>\n    <bpmn2:sequenceFlow id=\"SequenceFlow_1s6hi6r\" sourceRef=\"UserTask_09wiquf\" targetRef=\"EndEvent_02vx5jj\" />\n  </bpmn2:process>\n  <bpmndi:BPMNDiagram id=\"BPMNDiagram_ChangeRequest-Committee-default_diagram\">\n    <bpmndi:BPMNPlane id=\"BPMNDiagram_ChangeRequest-Committee-default\" bpmnElement=\"ChangeRequest-Committee-default1768127318174\">\n      <bpmndi:BPMNShape id=\"BPMNDiagram_ChangeRequest-Committee-defaultChangeRequest-Committee-default-pool-participant\" bpmnElement=\"ChangeRequest-Committee-default-pool-participant\" isHorizontal=\"true\">\n        <dc:Bounds x=\"248\" y=\"98\" width=\"1040\" height=