/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER cascade_soft_delete_project_cr
AFTER UPDATE ON project
FOR EACH ROW
BEGIN
    DECLARE days_to_delete INT;
    
    IF OLD.deletedatetime IS NULL AND NEW.deletedatetime IS NOT NULL THEN
        IF is_automatic_deletion_enabled() THEN
            SET days_to_delete = get_days_to_automatically_delete();
            
            IF days_to_delete = 0 THEN
                UPDATE changerequest 
                SET Deleted_At = NEW.deletedatetime,
                    LastUserChange = NULL,
                    scheduled_delete_at = NULL
                WHERE Reference = CONCAT('Project ', NEW.id) 
                  AND Deleted_At IS NULL;
            ELSE
                UPDATE changerequest 
                SET scheduled_delete_at = DATE_ADD(NEW.deletedatetime, INTERVAL days_to_delete DAY),
                    LastUserChange = NULL
                WHERE Reference = CONCAT('Project ', NEW.id) 
                  AND Deleted_At IS NULL
                  AND scheduled_delete_at IS NULL;
            END IF;
        END IF;
    END IF;
    IF OLD.deletedatetime IS NOT NULL AND NEW.deletedatetime IS NULL THEN
        UPDATE changerequest 
        SET Deleted_At = NULL,
            scheduled_delete_at = NULL,
            Updated_At = NOW(),
            LastUserChange = NULL
        WHERE Reference = CONCAT('Project ', NEW.id);
    END IF;
END */;;
DELIMITER ;
