INSERT INTO `static_pages` VALUES (1,'Find Out More','axon.local:9999/about','-',0,'<div class=\"hero-unit\"><h1>Welcome to <br/>abdo alaa application.</h1><p class=\"description\">Axon Data Governance is our collaborative and shared view of the business. Discover how we depend on each other to deliver, where changes are planned, and how projects are impacted. Trace the lifecycle of information and connect with a broad community of stakeholders with clearly defined responsibilities.</p><p><a href=\"/search\" class=\"hero-explore\"><i class=\"icon-search4\"></i> Explore with Unison &rarr;</a></p>{% if app.user == \' %}<p><a href=\"/login\" class=\"hero-login openLoginPopup\"><i class=\"icon-reading\"></i> Login and start contributing &rarr;</a></p>{% endif %}<p><a href=\"/about\" class=\"hero-more\"><i class=\"icon-question7\"></i> Find out more &rarr;</a></p></div>'),(2,'Homepage','axon.local:9999/home','-',1,'<div class=\"hero-unit\"><h1>Welcome to <br/>abdo alaa application.</h1><p class=\"description\">Axon Data Governance is our collaborative and shared view of the business. Discover how we depend on each other to deliver, where changes are planned, and how projects are impacted. Trace the lifecycle of information and connect with a broad community of stakeholders with clearly defined responsibilities.</p><p><a href=\"/search\" class=\"hero-explore\"><i class=\"icon-search4\"></i> Explore with Unison &rarr;</a></p>{% if app.user == \' %}<p><a href=\"/login\" class=\"hero-login openLoginPopup\"><i class=\"icon-reading\"></i> Login and start contributing &rarr;</a></p>{% endif %}<p><a href=\"/about\" class=\"hero-more\"><i class=\"icon-question7\"></i> Find out more &rarr;</a></p></div>'),(3,'Menu - Interface Tip','axon.local:9999/menu-interface-tip','menu',0,'It enables users to manage the content of various pages within Axon, e.g. Home Page, Help Pages. User must be comfortable with HTML to maintain this.'),(4,'Menu - Regulator Tip','axon.local:9999/menu-regulat