CREATE DEFINER=`root`@`localhost` PROCEDURE `drop_all_cascade_triggers`()
BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE trg_name VARCHAR(255);

    DECLARE cur CURSOR FOR
        SELECT TRIGGER_NAME
        FROM information_schema.TRIGGERS
        WHERE TRIGGER_SCHEMA = 'project'
          AND TRIGGER_NAME LIKE 'cascade_soft_delete_%';

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO trg_name;
        IF done = 1 THEN
            LEAVE read_loop;
        END IF;

        SET @sql = CONCAT('DROP TRIGGER IF EXISTS `', trg_name, '`');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END LOOP;

    CLOSE cur;
END ;;
